CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, nama TEXT NOT NULL, username TEXT UNIQUE NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN('buyer','vendor')), tgl_lahir TEXT, telp TEXT, alamat TEXT);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vendors(id INTEGER PRIMARY KEY, user_id INTEGER UNIQUE NOT NULL REFERENCES users(id), nama_toko TEXT NOT NULL, negara TEXT, kota TEXT, rating REAL DEFAULT 5, selesai INTEGER DEFAULT 0, kategori TEXT, deskripsi TEXT, estimasi TEXT DEFAULT '7–14 hari', aktif INTEGER DEFAULT 1, paypal TEXT);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, vendor_id INTEGER NOT NULL REFERENCES vendors(id), nama TEXT NOT NULL, kategori TEXT, harga INTEGER NOT NULL, jasa INTEGER NOT NULL, stok INTEGER DEFAULT 5, deskripsi TEXT, foto TEXT, rating REAL DEFAULT 5, ulasan INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS favorites(user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, product_id INTEGER REFERENCES products(id) ON DELETE CASCADE, PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS cart_items(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, product_id INTEGER REFERENCES products(id) ON DELETE CASCADE, qty INTEGER DEFAULT 1, dipilih INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, buyer_id INTEGER NOT NULL REFERENCES users(id), vendor_id INTEGER NOT NULL REFERENCES vendors(id), product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN('menunggu','diterima','dikemas','siap','dikirim','selesai','ditolak')), ongkir INTEGER DEFAULT 45000, biaya_impor INTEGER DEFAULT 0, warna TEXT, resi TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, judul TEXT, isi TEXT, rute TEXT, label TEXT, dibaca INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY, buyer_id INTEGER NOT NULL REFERENCES users(id), vendor_id INTEGER NOT NULL REFERENCES vendors(id), pengirim TEXT CHECK(pengirim IN('b','v')), isi TEXT NOT NULL, waktu TEXT);
